ControlPropertyState.AutoRuleBindingString:
UpdateContext({varCntSelect: false});
UpdateContext({varCashAdvanceStatusFilter: Blank()});
UpdateContext({varSelectedCashAdvance: Blank()});
UpdateContext({varCntDelete: false});
Refresh('Cash advances (mserp)');
Clear(colSelectedCashAdvanceIds);
Reset(scrCashAdvance_Gallery);
Reset(ComboBox_CashAdvanceStatusFilter);
Reset(txt_CashAdvanceDateFilter);

If(
    varAppMode = "CashAdvance",
    Set(varSelectedTab, 4);
    Navigate('Cash Advance - List Screen', ScreenTransition.Fade),
    If(
        varAppMode = "AirfareAllowance",
        Set(varSelectedTab, 4);
        Navigate('Travel - List Screen', ScreenTransition.Fade),
        UpdateContext({varcntShowFilter: false});
        Set(varSelectedTab, 4);
        Navigate('Approvals - List Screen', ScreenTransition.Fade, {varFiltersApplied:false, varSelectedProjects:Blank(), varSelectedUsers: Blank(), varcntSelectedStatus:1});
        Reset(scr25_cmb_Project);
        Reset(scr25_cmb_User)
    )
)

If(
    varCntSelect,
    If(
        IsBlank(LookUp(colSelectedCashAdvanceIds, cashAdvanceNumber = ThisItem.'Cash advance number')),
        Collect(colSelectedCashAdvanceIds, {cashAdvanceNumber: ThisItem.'Cash advance number'}),
        RemoveIf(colSelectedCashAdvanceIds, cashAdvanceNumber = ThisItem.'Cash advance number')
    ),
    Set(varSelectedCashAdvance, ThisItem);
    If(
        ThisItem.'Cash advance status' = 'Cash advance status (mserp)'.Draft,
        Set(varIsCreateCashAdvance, false);
        Navigate('Cash Advance - Edit Screen', ScreenTransition.Fade),
        Notify("Cash Advance View Only Screen is not yet implemented", NotificationType.Information, 3000)
    )
)

Set(varSelectedCashAdvance, Blank());
Set(varIsCreateCashAdvance, true);
Navigate('Cash Advance - Edit Screen', ScreenTransition.Fade)
